const raw = typeof newValue === 'string' ? newValue : '';
if (raw.length >= minimum && raw.trim().length < minimum) {
  return minimum === 1 ? 'Enter a name, not only whitespace.' : 'Use at least 12 characters after removing leading and trailing whitespace.';
}

if (!event || event.defaultPrevented || event.isComposing || event.repeat || event.ctrlKey || event.metaKey || event.altKey || event.shiftKey) { return; }
if (event.key === 'Enter' && event.target && event.target.tagName === 'INPUT') {
  $ctrl.handleContactPreview(event);
}

if (event && typeof event.preventDefault === 'function') { event.preventDefault(); }
$ctrl.attempted = true;
$ctrl.lastAttempt = JSON.stringify($ctrl.contactForm);
$ctrl.preview = null;
const draft = $ctrl.contactForm || {};
const rawName = typeof draft.name === 'string' ? draft.name : '';
const rawEmail = typeof draft.email === 'string' ? draft.email : '';
const rawMessage = typeof draft.message === 'string' ? draft.message : '';
const name = rawName.trim();
const email = rawEmail.trim();
const message = rawMessage.trim();
// Core constraints and trim-aware rules must agree before showing a preview.
const valid = name.length >= 1 && rawName.length <= 100 && email.length > 0 && rawEmail.length <= 254 && new RegExp($ctrl.emailPattern).test(rawEmail) && message.length >= 12 && rawMessage.length <= 4000;
let form = null;
const target = event && event.target;
if (target && typeof target.closest === 'function') { form = target.closest('form'); }
const nativeValid = !form || typeof form.reportValidity !== 'function' || form.reportValidity();
if (!valid || !nativeValid) {
  $ctrl.feedbackStatus = 'error';
  $ctrl.feedbackMessage = 'Preview unavailable. Review the highlighted fields and the limits above. Nothing has been sent.';
  return;
}
$ctrl.preview = {name: name, email: email, message: message};
$ctrl.feedbackStatus = 'ready';
$ctrl.feedbackMessage = 'Local preview ready — NOT sent. No email or backend is connected; delivery is not configured.';
